        vehiclesActive: { en: "Vehicles active", si: "ක්‍රියාත්මක රථ", ta: "செயலில் உள்ள வாகனங்கள்" },
        avgDwellTime: { en: "Avg. dwell time", si: "සාමාන්‍ය රැඳී සිටින කාලය", ta: "சராசரி தங்கும் நேரம்" },
