      eyebrow: { en: "Earnings calculator", si: "ආදායම් ගණකය", ta: "வருமான கால்குலேட்டர்" },
      headline: { en: "See exactly what you could earn.", si: "ඔබට උපයාගත හැකි මුදල හරියටම බලන්න.", ta: "நீங்கள் சம்பாதிக்கக்கூடியதை சரியாகப் பாருங்கள்." },
